import{_ as t,o as a,c as o,ah as r}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Catalogue and QCM banks","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/coordinateur/catalogue.md","filePath":"src/en/guide/coordinateur/catalogue.md"}'),n={name:"en/guide/coordinateur/catalogue.md"};function s(i,e,d,h,g,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="catalogue-and-qcm-banks" tabindex="-1">Catalogue and QCM banks <a class="header-anchor" href="#catalogue-and-qcm-banks" aria-label="Permalink to &quot;Catalogue and QCM banks&quot;">​</a></h1><p>The Pedagogical Coordinator keeps the catalogue of trainings and the admission test questions. The Administrator can do the same. Everything takes place in the <strong>Training</strong> section.</p><h2 id="the-catalogue" tabindex="-1">The catalogue <a class="header-anchor" href="#the-catalogue" aria-label="Permalink to &quot;The catalogue&quot;">​</a></h2><p><strong>Training → Catalogue</strong> lists the programs with their code, category, formats, duration and status: <strong>Draft</strong>, <strong>Published</strong> or <strong>Archived</strong>. Only a published program is visible on the NextBoxx website.</p><h3 id="creating-a-program" tabindex="-1">Creating a program <a class="header-anchor" href="#creating-a-program" aria-label="Permalink to &quot;Creating a program&quot;">​</a></h3><p><strong>New program</strong> asks for a code, a title, a category and, for the Career Path category, whether it is the <strong>Web &amp; Mobile Development package</strong> (700 h). The code starts with the category prefix followed by two digits (for example <code>NB.FP.01</code>). <strong>The code, category and package no longer change after creation</strong>: the code is the program&#39;s permanent key.</p><p>The teaching content is entered <strong>once per program</strong>: objectives, teaching methods, prerequisites, logistics, and the <strong>competency blocks</strong> in their teaching order, each with its duration in weeks (the total is compared with the program&#39;s duration). Each block carries its <strong>Sève gradebook code</strong> (<code>KURA-BLOC-{id}</code>), which trainers copy into Sève.</p><p>The <strong>formats</strong> offered are to be ticked: online, hybrid, in person.</p><h3 id="publishing-unpublishing-archiving" tabindex="-1">Publishing, unpublishing, archiving <a class="header-anchor" href="#publishing-unpublishing-archiving" aria-label="Permalink to &quot;Publishing, unpublishing, archiving&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Condition</th></tr></thead><tbody><tr><td><strong>Publish</strong></td><td>At least one format, objectives and at least one block. The screen lists what is missing</td></tr><tr><td><strong>Unpublish</strong> or <strong>Archive</strong></td><td>Impossible if an open, confirmed or in-progress cohort depends on it</td></tr><tr><td><strong>Restore as draft</strong></td><td>For an archived program</td></tr><tr><td><strong>Delete</strong></td><td>Only a draft that was never published</td></tr></tbody></table><h3 id="the-price-grid" tabindex="-1">The price grid <a class="header-anchor" href="#the-price-grid" aria-label="Permalink to &quot;The price grid&quot;">​</a></h3><p>The price is <strong>never entered freely</strong>: it comes from the <strong>price grid</strong>, by category and format. <strong>Training → Catalogue → Price grid</strong> shows the prices in force (in FCFA, excluding tax) and lets you <strong>schedule a change</strong> from a date. A change only applies to <strong>cohorts opened after that date</strong>: it is never retroactive, and an already open cohort keeps its prices.</p><h2 id="qcm-banks" tabindex="-1">QCM banks <a class="header-anchor" href="#qcm-banks" aria-label="Permalink to &quot;QCM banks&quot;">​</a></h2><p>The admission test draws on a bank of <strong>20 questions per program</strong>. <strong>Catalogue → QCM banks</strong> gives the state of each bank: <strong>Validated</strong>, <strong>To validate</strong> or <strong>Missing</strong>. Without a validated bank, candidates cannot take the test and <strong>no cohort of that program can open</strong>.</p><p>Only the Pedagogical Coordinator and the Administrator have access. Trainers and advisors do not.</p><h3 id="importing" tabindex="-1">Importing <a class="header-anchor" href="#importing" aria-label="Permalink to &quot;Importing&quot;">​</a></h3><ol><li>Download the category&#39;s <strong>template</strong>: an <code>.xlsx</code> workbook with one sheet per non-archived program, named by its code.</li><li>Fill in each sheet: <strong>exactly 20 rows</strong>, with the columns <code>énoncé</code>, <code>choix_1</code> to <code>choix_4</code> and <code>réponse_correcte</code> (the number of the right choice, from 1 to 4).</li><li>Choose the category, the workbook, then <strong>Import</strong>.</li></ol><p>Each sheet is processed <strong>independently</strong>: a compliant sheet creates a draft batch, a faulty sheet (wrong structure, unknown code, 18 rows instead of 20, answer missing from the choices) is rejected alone, with the <strong>row and column</strong> at fault. A report per sheet is displayed. The file is <strong>never kept</strong>, in success or failure: only its name is logged.</p><h3 id="validating" tabindex="-1">Validating <a class="header-anchor" href="#validating" aria-label="Permalink to &quot;Validating&quot;">​</a></h3><p>Import and validation are <strong>two separate actions</strong>. Open the program&#39;s bank, review the questions, then <strong>Validate the bank</strong>. The questions of the program&#39;s other batches are then removed from the draw (they stay in the database).</p><ul><li>A <strong>new import</strong> never replaces a validated bank: it creates a batch to validate, and <strong>the old bank stays in service</strong> until the new batch is validated. You can thus re-import a single sheet to correct a program.</li><li><strong>Editing a validated question</strong> puts it back to &quot;To validate&quot;: the bank must be validated again to be used.</li></ul><p>The bank is to be reviewed <strong>every year</strong>.</p>',22)])])}const u=t(n,[["render",s]]);export{p as __pageData,u as default};
